-- MediTrack schema + sample data (all fictional). PostgreSQL / Neon.
DROP TABLE IF EXISTS "Billing", "Prescriptions", "Appointments", "Doctors", "Patients" CASCADE;

CREATE TABLE "Patients" (
  "Patient_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" VARCHAR(100),
  "Age" INTEGER,
  "Gender" VARCHAR(10),
  "Contact" VARCHAR(15),
  "Email" VARCHAR(100),
  "Address" VARCHAR(100)
);


CREATE TABLE "Doctors" (
  "Doctor_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" VARCHAR(100),
  "Specialization" VARCHAR(50),
  "Fee" NUMERIC(10, 2),
  "Experience_Years" INTEGER
);


CREATE TABLE "Appointments" (
  "Appointment_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Patient_ID" INTEGER REFERENCES "Patients" ("Patient_ID"),
  "Doctor_ID" INTEGER REFERENCES "Doctors" ("Doctor_ID"),
  "Appointment_Date" DATE,
  "Status" VARCHAR(20)
);


CREATE TABLE "Prescriptions" (
  "Prescription_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Appointment_ID" INTEGER REFERENCES "Appointments" ("Appointment_ID"),
  "Medicine" VARCHAR(100),
  "Dosage" VARCHAR(20),
  "Duration_Days" INTEGER
);


CREATE TABLE "Billing" (
  "Bill_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Appointment_ID" INTEGER REFERENCES "Appointments" ("Appointment_ID"),
  "Amount" NUMERIC(10, 2),
  "Payment_Method" VARCHAR(50),
  "Payment_Status" VARCHAR(20)
);


SELECT setval(pg_get_serial_sequence('"Patients"', 'Patient_ID'), (SELECT MAX("Patient_ID") FROM "Patients"));
SELECT setval(pg_get_serial_sequence('"Doctors"', 'Doctor_ID'), (SELECT MAX("Doctor_ID") FROM "Doctors"));
SELECT setval(pg_get_serial_sequence('"Appointments"', 'Appointment_ID'), (SELECT MAX("Appointment_ID") FROM "Appointments"));
SELECT setval(pg_get_serial_sequence('"Prescriptions"', 'Prescription_ID'), (SELECT MAX("Prescription_ID") FROM "Prescriptions"));
SELECT setval(pg_get_serial_sequence('"Billing"', 'Bill_ID'), (SELECT MAX("Bill_ID") FROM "Billing"));
